const lessons = [
  {title:'从一句你好开始',name:'打招呼与告别',fr:'Les salutations',description:'用四句最常用的表达，开启你的第一段法语对话。',tip:'Bonjour 适合白天见面时使用；晚上打招呼可以说 Bonsoir。',words:[['Bonjour','你好 / 日安','bɔ̃.ʒuʁ'],['Salut','嗨 / 再见（熟人之间）','sa.ly'],['Merci','谢谢','mɛʁ.si'],['Au revoir','再见','o ʁə.vwaʁ']]},
  {title:'很高兴认识你',name:'介绍自己',fr:'Se présenter',description:'说出你的名字，介绍你来自哪里，再认识一位新朋友。',tip:'Je m’appelle 后面直接接名字。初次见面，男性说 Enchanté，女性写作 Enchantée，读音相同。',words:[['Je m’appelle…','我的名字是……','ʒə ma.pɛl'],['Enchanté / Enchantée','很高兴认识你','ɑ̃.ʃɑ̃.te'],['Je viens de Chine','我来自中国','ʒə vjɛ̃ də ʃin'],['Et vous ?','您呢？','e vu']]},
  {title:'来一杯咖啡吧',name:'在咖啡馆',fr:'Au café',description:'从点单到结账，练习在法国咖啡馆会用到的表达。',tip:'点单时加上 s’il vous plaît，会更礼貌。Un café 在法国通常指一小杯浓缩咖啡。',words:[['Un café, s’il vous plaît','请给我一杯咖啡','œ̃ ka.fe sil vu plɛ'],['Un croissant','一个羊角面包','œ̃ kʁwa.sɑ̃'],['L’addition, s’il vous plaît','请结账','la.di.sjɔ̃ sil vu plɛ'],['C’est délicieux !','真好吃！','sɛ de.li.sjø']]},
  {title:'去发现这座城市',name:'问路与出行',fr:'En ville',description:'找地铁、问方向，一起走进城市的日常生活。',tip:'向陌生人问路时，可以先说 Bonjour，再用 Excusez-moi 礼貌地引起对方注意。',words:[['Excusez-moi','打扰一下 / 对不起','ɛks.ky.ze mwa'],['Où est le métro ?','地铁在哪里？','u ɛ lə me.tʁo'],['À gauche','向左 / 在左边','a ɡoʃ'],['À droite','向右 / 在右边','a dʁwat']]}
];
const $ = s => document.querySelector(s);
let lessonIndex=0, mode='learn', cardIndex=0, flipped=false, questionIndex=0, score=0, answered=false;
let completed=[];
try{const saved=JSON.parse(localStorage.getItem('petit-progress')||'[]');if(Array.isArray(saved))completed=[...new Set(saved.filter(n=>Number.isInteger(n)&&n>=0&&n<lessons.length))];}catch{}
const soundIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M11 4 5 9H2v6h3l6 5V4Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>';
function speakButton(i){return `<button class="sound" data-speak="${i}" aria-label="朗读：${lessons[lessonIndex].words[i][0]}">${soundIcon}</button>`;}
function notify(message){$('#announcement').textContent=message;$('#announcement').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#announcement').hidden=true,4500);}
function renderNav(){ $('#lessons').innerHTML=lessons.map((l,i)=>`<button class="lesson-link ${i===lessonIndex?'active':''}" data-lesson="${i}" ${i===lessonIndex?'aria-current="step"':''}><span class="lesson-number">0${i+1}</span><span><strong>${l.name}</strong><small lang="fr">${l.fr}</small></span><span class="arrow">${completed.includes(i)?'✓':'↗'}</span></button>`).join('');$('#completed-count').textContent=`${completed.length} / 4`;$('#course-progress').value=completed.length;}
function setMode(next){mode=next;cardIndex=0;flipped=false;questionIndex=0;score=0;answered=false;render();}
function selectLesson(i){lessonIndex=i;setMode('learn');}
function render(){const l=lessons[lessonIndex];renderNav();$('#lesson-label').textContent=`LEÇON 0${lessonIndex+1} · ${l.fr.toUpperCase()}`;$('#lesson-title').textContent=l.title;$('#lesson-description').textContent=l.description;document.querySelectorAll('[data-mode]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.mode===mode));b.tabIndex=b.dataset.mode===mode?0:-1;});$('#study-panel').setAttribute('aria-labelledby',`tab-${mode}`);
if(mode==='learn'){$('#study-panel').innerHTML=l.words.map((w,i)=>`<div class="phrase"><div class="phrase-main"><span class="french" lang="fr">${w[0]}</span><span class="ipa" lang="fr">/${w[2]}/</span><div class="translation">${w[1]}</div></div>${speakButton(i)}</div>`).join('')+`<div class="tip">小提示 · ${l.tip}</div><div class="panel-footer"><small>点击喇叭，听一听法语怎么说</small><button class="primary" data-action="cards">开始记一记 →</button></div>`;}
if(mode==='cards'){const w=l.words[cardIndex];$('#study-panel').innerHTML=`<div class="card-count"><span>单词卡 · ${cardIndex+1} / ${l.words.length}</span>${speakButton(cardIndex)}</div><button class="flashcard" data-action="flip" aria-label="${flipped?'返回法语':'翻卡查看中文'}"><span class="eyebrow">${flipped?'中文释义':'你还记得它的意思吗？'}</span><span class="french" ${flipped?'':'lang="fr"'}>${flipped?w[1]:w[0]}</span><small>点击卡片${flipped?'返回法语':'查看释义'} ↻</small></button><div class="panel-footer"><button class="secondary" data-action="prev" ${cardIndex===0?'disabled':''}>上一张</button><button class="primary" data-action="next-card">${cardIndex===l.words.length-1?'开始小测验 →':'下一张 →'}</button></div>`;}
if(mode==='quiz') renderQuiz();}
function renderQuiz(){const l=lessons[lessonIndex];if(questionIndex===l.words.length){const passed=score===l.words.length;if(passed&&!completed.includes(lessonIndex)){completed.push(lessonIndex);try{localStorage.setItem('petit-progress',JSON.stringify(completed));}catch{notify('当前浏览器无法保存进度，本次学习仍可继续。');}renderNav();}$('#study-panel').innerHTML=`<div class="result"><p class="eyebrow">${passed?'TRÈS BIEN !':'ENCORE UN PETIT EFFORT'}</p><strong>${score} <span style="font-size:22px;color:var(--muted)">/ ${l.words.length}</span></strong><h3>${passed?'太棒了，这一课完成啦！':'再练一遍，就会更熟悉。'}</h3><p>${passed?'把今天学会的表达，大声说给自己听。':'答对全部题目即可完成课程，可以先回顾表达。'}</p></div><div class="panel-footer"><button class="secondary" data-action="learn">回顾表达</button><button class="primary" data-action="${passed&&lessonIndex<lessons.length-1?'next-lesson':'retry'}">${passed&&lessonIndex<lessons.length-1?'学习下一课 →':'再测一次 →'}</button></div>`;return;}
const order=[0,1,2,3].map(n=>(n+questionIndex+1)%4);$('#study-panel').innerHTML=`<div class="card-count"><span>选择正确的法语表达</span><span>${questionIndex+1} / ${l.words.length}</span></div><h3 class="quiz-prompt">“${l.words[questionIndex][1]}” 用法语怎么说？</h3><div class="options">${order.map(i=>`<button class="option" data-answer="${i}" lang="fr">${l.words[i][0]}</button>`).join('')}</div><p class="feedback" role="status"></p><div class="panel-footer"><small>答对全部 4 题，完成这一课</small><button class="primary" data-action="next-question" hidden>下一题 →</button></div>`;}
function answer(i){if(answered||mode!=='quiz'||questionIndex>=4)return;answered=true;const correct=i===questionIndex;if(correct)score++;document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(Number(b.dataset.answer)===questionIndex)b.classList.add('correct');else if(Number(b.dataset.answer)===i)b.classList.add('wrong');});$('.feedback').textContent=correct?'答对了！Très bien !':`还差一点。正确答案是：${lessons[lessonIndex].words[questionIndex][0]}`;const next=$('[data-action="next-question"]');next.hidden=false;next.textContent=questionIndex===3?'查看结果 →':'下一题 →';next.focus();}
function speak(i){if(!('speechSynthesis' in window)){notify('当前浏览器不支持语音朗读，可以参考音标学习。');return;}const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang.toLowerCase().startsWith('fr'));if(!voice){notify('设备暂无可用的法语语音，请在系统语音设置中添加法语后重试。');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(lessons[lessonIndex].words[i][0].split(' / ')[0].replace('…',''));utterance.lang='fr-FR';utterance.voice=voice;utterance.rate=.8;utterance.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')notify('朗读暂时不可用，请检查设备的语音设置。');};speechSynthesis.speak(utterance);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lesson!==undefined){selectLesson(Number(b.dataset.lesson));return;}if(b.dataset.mode){setMode(b.dataset.mode);return;}if(b.dataset.speak!==undefined){speak(Number(b.dataset.speak));return;}if(b.dataset.answer!==undefined){answer(Number(b.dataset.answer));return;}switch(b.dataset.action){case 'learn':setMode('learn');break;case 'cards':setMode('cards');break;case 'retry':setMode('quiz');break;case 'flip':flipped=!flipped;render();$('[data-action="flip"]').focus();break;case 'prev':cardIndex=Math.max(0,cardIndex-1);flipped=false;render();break;case 'next-card':if(cardIndex<3){cardIndex++;flipped=false;render();}else setMode('quiz');break;case 'next-question':if(answered){questionIndex++;answered=false;renderQuiz();}break;case 'next-lesson':selectLesson(Math.min(3,lessonIndex+1));break;}});
$('.tabs').addEventListener('keydown',e=>{const modes=['learn','cards','quiz'];let i=modes.indexOf(mode);if(e.key==='ArrowRight')i=(i+1)%3;else if(e.key==='ArrowLeft')i=(i+2)%3;else if(e.key==='Home')i=0;else if(e.key==='End')i=2;else return;e.preventDefault();setMode(modes[i]);$(`#tab-${mode}`).focus();});
if('speechSynthesis' in window)speechSynthesis.getVoices();
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_french_lesson',description:'Open one of the four beginner French lessons without marking it complete.',inputSchema:{type:'object',properties:{lesson:{type:'integer',minimum:1,maximum:4}},required:['lesson'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!Number.isInteger(input?.lesson)||input.lesson<1||input.lesson>4)throw new Error('lesson must be 1–4');selectLesson(input.lesson-1);return{lesson:input.lesson,title:lessons[lessonIndex].title,mode};}})).catch(()=>{});}catch{}}
